import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-sociology-health-disparities-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Define social determinants of health.`]: {
    question: r`A county health department wants to explain why two neighbourhoods served by the same hospital differ by 8 years in life expectancy. Which set of factors would count as social determinants of health?`,
    options: [r`Drug dosing, surgical skill, and imaging accuracy`, r`Tumor grade, viral load, and blood pressure level`, r`Housing quality, school funding, and grocery access`, r`Inherited alleles, blood type, and family history`],
    correctAnswer: 2,
    explanation: r`Social determinants are the non-medical conditions people live in, such as housing, education and food access. Drug dosing and surgical skill describe medical care itself, inherited alleles and blood type are biological traits, and tumor grade or viral load are clinical measures of disease rather than conditions that shape who gets sick.`,
  },
  [r`How does residential segregation affect health?`]: {
    question: r`A city district that was historically redlined is still majority-minority. It has no supermarket, sits beside a freight corridor, and lost its only clinic. Asthma admissions there are three times the city rate. The best sociological explanation is that residential segregation:`,
    options: [r`concentrates hazards and limits access to food and care`, r`selects for families with inherited lung vulnerability`, r`raises admissions only by improving case detection there`, r`reflects residents' shared preference for risky habits`],
    correctAnswer: 0,
    explanation: r`Segregation sorts groups into places with more pollution and fewer stores and clinics, and those conditions produce measurable outcome gaps. Blaming shared habits turns a structural cause into individual choice, an inherited vulnerability has no support in the scenario, and a district that lost its clinic does not have better case detection.`,
  },
  [r`What is medicalization?`]: {
    question: r`Over twenty years, ordinary grief lasting beyond a few months comes to be given a diagnostic code, a recommended drug, and specialist clinics. This change is an example of:`,
    options: [r`medicalization`, r`the sick role`, r`demedicalization`, r`stigmatization`],
    correctAnswer: 0,
    explanation: r`A normal human experience has been redefined as a condition for medicine to diagnose and treat, which is medicalization. Demedicalization is the reverse, when a condition stops being treated as medical. The sick role describes the rights and duties of an ill person, and stigmatization is social devaluation, neither of which describes a problem gaining a diagnosis.`,
  },
  [r`What is the difference between health equity and equality?`]: {
    question: r`In one school, 10% of children lack dental sealants; in another, 60% do. A first proposal sends one hygienist visit to each school. A second proposal sends five visits to the higher-need school and one to the other. The second proposal reflects:`,
    options: [r`equity, because every school gets the same`, r`equality, because every school gains`, r`equality, because resources follow need`, r`equity, because resources follow need`],
    correctAnswer: 3,
    explanation: r`Equity allocates according to need so that outcomes become comparable, which is what sending more visits to the higher-need school does. Equality means identical resources for everyone, which describes the first proposal. The options that pair equality with following need, or equity with giving every school the same, attach the right reason to the wrong term.`,
  },
  [r`Contrast the sick role and illness experience.`]: {
    question: r`Two researchers study people with lupus. The first asks what duties patients are excused from and what society expects of them in return. The second interviews patients about what living with the disease means to them. The researchers are studying, respectively:`,
    options: [r`the illness experience, then the sick role`, r`medicalization, then the illness experience`, r`the sick role, then the illness experience`, r`the sick role, then the social gradient`],
    correctAnswer: 2,
    explanation: r`Parsons' sick role is about social rights and obligations: exemption from duties in exchange for seeking care. The illness experience is the subjective, lived meaning of being ill, which is what the interviews capture. Reversing the order swaps the two ideas, medicalization is about redefining problems as medical, and the social gradient concerns health by socioeconomic status.`,
  },
  [r`What is the social gradient in health?`]: {
    question: r`A researcher claims that health differences by income are only a poverty effect. Which finding most directly contradicts the claim?`,
    options: [r`Adults below the poverty line die younger than all others`, r`Poor adults report more chronic illness than the wealthy`, r`Life expectancy is the same in every band above poverty`, r`Upper-middle earners outlive middle earners by two years`],
    correctAnswer: 3,
    explanation: r`The social gradient means health keeps improving with each step up in status, so a gap between two groups who are both well above poverty contradicts a threshold-only view. Worse health below the poverty line and more illness among poor adults both fit a pure poverty effect, and equal life expectancy above poverty is exactly what the threshold claim predicts.`,
  },
  [r`What is the inverse care law?`]: {
    question: r`A region has 40 primary care physicians per 100,000 people in its healthiest, wealthiest suburbs and 8 per 100,000 in the districts with the highest rates of diabetes and heart disease. This distribution illustrates:`,
    options: [r`the weathering effect`, r`the social gradient`, r`the Hispanic paradox`, r`the inverse care law`],
    correctAnswer: 3,
    explanation: r`The inverse care law states that good medical care is least available where need is greatest, which matches physician supply running opposite to disease burden. The social gradient describes health rising with status, not the supply of care. The Hispanic paradox is better than expected health despite lower status, and weathering is early physiological aging from chronic stress.`,
  },
  [r`Distinguish incidence from prevalence.`]: {
    question: r`On January 1, a town of 10,000 has 200 people living with type 2 diabetes. During the year, 50 residents are newly diagnosed. Which statement is correct?`,
    options: [r`Prevalence on January 1 is 2%; the 50 new cases measure incidence`, r`Incidence on January 1 is 0.5%; the 200 cases measure prevalence`, r`Prevalence on January 1 is 0.5%; the 200 cases measure incidence`, r`Incidence on January 1 is 2%; the 50 new cases measure prevalence`],
    correctAnswer: 0,
    explanation: r`Prevalence is all existing cases at a point in time: 200 of 10,000 is 2%. Incidence counts new cases over a period, here the 50 diagnosed during the year. The statements that call the January 1 figure incidence swap the two terms, and the 0.5% figures divide the 50 new cases by the population and then mislabel the result.`,
  },
  [r`Social capital contributes to health by:`]: {
    question: r`After a hip fracture, two retirees with the same income and insurance go home. One belongs to a congregation and a neighbourhood association whose members bring meals, drive her to therapy, and tell her about a free rehabilitation program. She recovers faster. The resource that explains the difference is:`,
    options: [r`health literacy`, r`economic capital`, r`cultural capital`, r`social capital`],
    correctAnswer: 3,
    explanation: r`Social capital is the support and resources a person can reach through networks, which is what the congregation and association supply. Cultural capital is knowledge, tastes and credentials, economic capital is money (the two have the same income), and health literacy is a person's own ability to obtain and use health information.`,
  },
  [r`Discrimination differs from prejudice in being:`]: {
    question: r`A clinic manager privately believes patients from one immigrant group are less reliable, but she schedules, treats, and bills every patient by exactly the same rules. A second manager holds no such belief but follows the owner's instruction to give that group the least convenient appointment slots. Which statement is correct?`,
    options: [r`Neither shows discrimination, because neither intends harm`, r`The first shows prejudice only; the second shows discrimination`, r`Both managers show prejudice and both show discrimination`, r`The first shows discrimination only; the second shows prejudice`],
    correctAnswer: 1,
    explanation: r`Prejudice is an attitude and discrimination is behavior. The first manager holds a biased belief but acts equally, so she shows prejudice without discrimination; the second treats a group unequally without holding the belief. Swapping the labels confuses attitude with action, and discrimination does not require an intent to harm.`,
  },
  [r`The Hispanic paradox refers to:`]: {
    question: r`A national dataset shows that a Hispanic immigrant population has lower average income and education than non-Hispanic white adults, yet similar or longer life expectancy. Which explanation matches the accounts usually proposed for this finding?`,
    options: [r`Strong social ties and selective migration of healthy people`, r`Greater allostatic load from chronic stress over the years`, r`Higher average income and broader insurance coverage there`, r`Faster uptake of new medical technology by this population`],
    correctAnswer: 0,
    explanation: r`The Hispanic paradox is better than expected health despite lower socioeconomic status, usually attributed to social cohesion and the tendency of healthier people to migrate. Higher income contradicts the stated data, faster uptake of technology is what advantaged groups show, and greater allostatic load would predict worse health, not better.`,
  },
  [r`Medicalization can worsen inequality by:`]: {
    question: r`A city with a shortage of affordable housing sees rising distress among evicted families. Officials respond by funding anxiety screening and prescriptions for the families and nothing else. A critic drawing on the concept of medicalization would object that this response:`,
    options: [r`treats an individual disorder as a structural problem`, r`recasts a structural problem as an individual disorder`, r`removes a real medical disorder from physician oversight`, r`denies the families any access to the sick role at all`],
    correctAnswer: 1,
    explanation: r`Medicalization can deepen inequality by expanding medical authority over social problems, so a housing shortage is handled as each person's pathology while its cause is left alone. Removing a disorder from physician oversight describes demedicalization, treating a disorder as structural is the opposite error, and a diagnosis grants access to the sick role instead of denying it.`,
  },
  [r`Institutional discrimination operates through:`]: {
    question: r`A transplant center requires every candidate to have a car and a caregiver who can take six weeks off work. No staff member holds biased views and the rule is applied to everyone, yet low-income patients are listed far less often. This is best described as:`,
    options: [r`individual discrimination`, r`institutional discrimination`, r`explicit personal prejudice`, r`implicit provider prejudice`],
    correctAnswer: 1,
    explanation: r`Institutional discrimination works through policies and practices that produce unequal outcomes, and it can persist with no individual intending harm. Individual discrimination would require a person treating someone unequally, and both explicit and implicit prejudice are attitudes held by people, which the scenario rules out.`,
  },
  [r`Why can improved medical technology sometimes WIDEN disparities?`]: {
    question: r`A continuous glucose monitor reaches the market. Five years later diabetes control has improved overall, but the gap between high-income and low-income patients is larger than before. The most likely reason is that:`,
    options: [r`higher-income patients adopted the device sooner`, r`lower-income patients adopted the device sooner`, r`incidence rose fastest among high-income adults`, r`the device works less well in low-income bodies`],
    correctAnswer: 0,
    explanation: r`Advantaged groups have the money, knowledge and connections to take up innovations first, so a new technology can widen a gap even as average health improves. Earlier adoption by lower-income patients would narrow the gap, there is no biological difference in how the device works by income, and rising incidence among high-income adults would not improve their control.`,
  },
  [r`Cultural capital refers to:`]: {
    question: r`Two patients have the same income, insurance, and number of friends and relatives. One holds a graduate degree, speaks in the same style as her physicians, and is at ease in professional settings; her concerns are taken more seriously. Bourdieu would attribute her advantage to:`,
    options: [r`cultural capital`, r`social capital`, r`economic capital`, r`social mobility`],
    correctAnswer: 0,
    explanation: r`Cultural capital is the knowledge, tastes and credentials that confer advantage, such as a degree and a professional manner of speaking. Social capital refers to networks, which are equal here, and economic capital is money, also equal. Social mobility is movement between class positions, not a resource used in an encounter.`,
  },
  [r`What is the epidemiological transition?`]: {
    question: r`A country industrializes over 60 years. Its leading causes of death change from diarrheal disease and tuberculosis to stroke and cancer. In its poorest provinces, clinics now see rising diabetes while malaria remains common. These two observations show:`,
    options: [r`the demographic transition, then a social gradient`, r`the epidemiological transition, then weathering`, r`the epidemiological transition, then a double burden`, r`medicalization, then the inverse care law at work`],
    correctAnswer: 2,
    explanation: r`The shift from infectious to chronic causes of death with development is the epidemiological transition, and facing both kinds of disease at once is the double burden seen in low-income settings. The demographic transition concerns birth and death rates, weathering is stress-related early aging in individuals, and medicalization is redefining problems as medical.`,
  },
  [r`{{c1::Medicalization}} turns nonmedical problems into illnesses (ADHD, baldness); {{c2::demedicalization}} reverses it — homosexuality left the DSM in 1973.`]: {
    question: r`A professional body removes a behavior from its diagnostic manual, insurers stop paying for its treatment, and physicians no longer regard it as a condition. This process is:`,
    options: [r`deinstitutionalization`, r`biographical disruption`, r`medicalization`, r`demedicalization`],
    correctAnswer: 3,
    explanation: r`Demedicalization is the reversal of medicalization: something once defined as an illness stops being treated as a medical matter. Medicalization runs the other way, turning a nonmedical problem into a diagnosis. Deinstitutionalization is moving patients out of long-stay facilities, and biographical disruption is the upheaval of identity in chronic illness.`,
  },
  [r`Distinguish disease, illness, and sickness.`]: {
    question: r`A woman has severe fatigue and pain that upend her daily life. Extensive testing finds no pathology, and her employer and insurer refuse to recognise her as unwell. In the disease, illness, sickness framework, she has:`,
    options: [r`disease, without illness or sickness`, r`illness and sickness, without disease`, r`illness, without disease or sickness`, r`sickness, without disease or illness`],
    correctAnswer: 2,
    explanation: r`Illness is the person's subjective experience of suffering, which she clearly has. Disease is confirmed biomedical pathology, which testing did not find, and sickness is the social recognition of being unwell, which her employer and insurer withhold. Each other choice assigns her pathology or social recognition that the scenario says is absent.`,
  },
  [r`In life-course models, contrast a critical-period effect with an accumulation effect.`]: {
    question: r`Study 1: adults exposed to famine during the first trimester of gestation have more heart disease regardless of their later living conditions. Study 2: adult disease risk rises steadily with the number of years a person lived in poverty, whenever those years occurred. Studies 1 and 2 support, respectively:`,
    options: [r`a critical-period effect, then a second critical period`, r`a critical-period effect, then an accumulation effect`, r`an accumulation effect, then a critical-period effect`, r`an accumulation effect, then a second accumulation effect`],
    correctAnswer: 1,
    explanation: r`A critical-period effect is lasting harm from exposure in one developmental window, independent of later conditions, as in Study 1. An accumulation effect means insults add up, so the total duration of poverty matters and its timing does not, as in Study 2. The other choices reverse the two or apply one label to both studies.`,
  },
  [r`How can health disadvantage transmit across generations?`]: {
    question: r`Which finding would be the clearest example of health disadvantage passing from one generation to the next?`,
    options: [r`Immigrants show better health than their income would predict`, r`Workers in a lower job grade have more heart disease than managers`, r`Low birth weight after maternal deprivation predicts adult illness`, r`Adults who lose jobs in midlife report worse health one year later`],
    correctAnswer: 2,
    explanation: r`Transmission across generations means the parent's circumstances shape the child's health, for example maternal deprivation affecting fetal growth and later adult disease. Job loss harming a worker's own health and a gradient by job grade both concern one generation's own exposures, and better than expected immigrant health is a separate pattern.`,
  },
  [r`How do physicians act as gatekeepers of the sick role?`]: {
    question: r`An employee with disabling symptoms asks for paid medical leave. Her employer and insurer both say they can act only once a physician documents a diagnosis. This requirement shows that physicians:`,
    options: [r`control legitimate entry into the sick role`, r`determine the patient's illness experience`, r`reverse the medicalization of her symptoms`, r`create the social gradient in her workplace`],
    correctAnswer: 0,
    explanation: r`Medical certification is what legitimates illness for employers and insurers, so physicians act as gatekeepers of the sick role and its exemptions. Her illness experience is her own subjective account and exists with or without a note. A diagnosis would medicalize her symptoms, not reverse that, and the social gradient is a population pattern by status.`,
  },
  [r`What forces drive medicalization?`]: {
    question: r`A company with a new drug for mild shyness funds advertising that urges viewers to ask their doctor about it, and insurers will pay only if a diagnosis code is recorded. Diagnoses triple. Which pair of drivers of medicalization does this describe?`,
    options: [r`Patient advocacy groups and new detection technology`, r`Pharmaceutical marketing and insurer diagnosis rules`, r`New detection technology and demedicalization efforts`, r`Physician professional expansion and patient advocacy`],
    correctAnswer: 1,
    explanation: r`The advertising is pharmaceutical marketing that creates a treatable market, and the payment rule is insurers requiring a diagnosis for reimbursement. Patient advocacy, physician professional expansion and new detection technology are also real drivers, but none appears in this scenario, and demedicalization is the opposite process.`,
  },
  [r`What explains men's higher mortality despite women's higher morbidity?`]: {
    question: r`In a national dataset, men aged 25 to 44 die at about twice the rate of women the same age. Which breakdown of the excess male deaths would fit the standard sociological explanation?`,
    options: [r`Mostly autoimmune disease and chronic pain conditions`, r`Mostly complications from frequent physician visits`, r`Mostly injuries, overdoses, violence, and suicide`, r`Mostly nonfatal chronic illness recorded at checkups`],
    correctAnswer: 2,
    explanation: r`Higher male mortality is explained mainly by risk behaviors, hazardous work, violence and completed suicide, along with delayed help-seeking. Autoimmune and chronic pain conditions are more common in women and raise morbidity, not deaths. Men visit physicians less often, not more, and a nonfatal illness cannot account for excess deaths.`,
  },
  [r`How does implicit bias produce disparities in clinical care?`]: {
    question: r`Emergency physicians who sincerely endorse equal treatment are found, on chart review, to give pain medication for long-bone fractures less often to Black patients than to white patients reporting the same pain scores. The most likely mechanism is:`,
    options: [r`true group differences in pain biology`, r`implicit bias shaping pain assessment`, r`patients' lower health literacy scores`, r`explicit prejudice stated by clinicians`],
    correctAnswer: 1,
    explanation: r`Implicit bias is unconscious association that alters judgments such as pain assessment, even in clinicians who consciously value equal care. Explicit prejudice is ruled out by their sincere endorsement of equal treatment, health literacy does not change a reported pain score, and the belief in biological differences in pain is false and is itself one source of the bias.`,
  },
  [r`Contrast upstream and downstream interventions for health disparities.`]: {
    question: r`A city has high rates of childhood asthma in apartments with mold. Which response is an upstream intervention?`,
    options: [r`Handing families a pamphlet on avoiding asthma triggers`, r`Prescribing inhaled steroids to each child who has symptoms`, r`Enforcing housing codes that require landlords to remove mold`, r`Adding emergency department beds for severe asthma attacks`],
    correctAnswer: 2,
    explanation: r`Upstream interventions change the conditions that produce harm, here the housing itself. Inhalers and emergency beds treat individuals after harm has occurred, and a pamphlet is individual education that leaves the mold in place, so all three are downstream.`,
  },
  [r`The {{c1::SES gradient}} in health: outcomes improve at every step up the socioeconomic ladder, not merely above a poverty threshold.`]: {
    question: r`A health minister proposes that lifting every household just above the poverty line will end income-related health differences. Based on what is known about socioeconomic status and health, what would be expected among people above the line?`,
    options: [r`Health would still differ at each income step`, r`Health would decline as income rose further`, r`Health would be equal at every income step`, r`Health would differ only by insurance type`],
    correctAnswer: 0,
    explanation: r`The SES gradient means outcomes improve at every step up the ladder, so differences continue well above poverty. Equal health above the line is the threshold view that the gradient contradicts, declining health with rising income reverses the relationship, and the gradient appears even where everyone has the same coverage.`,
  },
  [r`Limited {{c1::health literacy}} — difficulty obtaining and using health information — impairs navigation and adherence, concentrating in low-SES groups.`]: {
    question: r`A fluent English speaker with full insurance and a pharmacy next door takes a twice-daily medication four times a day because he misread the label, and he cannot restate his discharge instructions. Which barrier is operating, and which remedy fits it?`,
    options: [r`Provider shortage; add clinic hours`, r`Limited health literacy; use teach-back`, r`Underinsurance; lower his deductible`, r`Language barrier; book an interpreter`],
    correctAnswer: 1,
    explanation: r`Difficulty obtaining and using health information is limited health literacy, and plain language with teach-back is the matched remedy. Cost is not the problem because he is fully insured, language is not because he is fluent, and a provider shortage does not explain misreading a label with a pharmacy next door.`,
  },
  [r`Being {{c1::uninsured}} or underinsured predicts delayed care, skipped medications, fewer screenings, and later-stage diagnoses.`]: {
    question: r`A registry compares breast cancer patients who had continuous insurance with patients who had none. Which finding is the signature result expected in the uninsured group?`,
    options: [r`A shorter delay between symptom and visit`, r`More tumors first found at a late stage`, r`More tumors first found by routine screens`, r`More tumors first found at an early stage`],
    correctAnswer: 1,
    explanation: r`Being uninsured predicts delayed care and fewer screenings, so cancers are diagnosed at later stages. Early-stage detection and detection by routine screening are more common with insurance, and the uninsured wait longer, not shorter, between a symptom and a visit.`,
  },
  [r`{{c1::Social epidemiology}} studies how social structure — class, race, gender, place — distributes disease and mortality across populations.`]: {
    question: r`Which research question is most characteristic of social epidemiology?`,
    options: [r`Why are heart attack rates patterned by neighborhood and class?`, r`Which statin dose best lowers this patient's LDL cholesterol?`, r`How does this patient describe the meaning of a heart attack?`, r`Which mutation in this patient's family raises cholesterol?`],
    correctAnswer: 0,
    explanation: r`Social epidemiology asks how social structure, such as class and place, distributes disease across populations: the causes of the causes. A family mutation and a statin dose are individual biomedical questions, and how one patient describes the meaning of a heart attack is a question about illness experience.`,
  },
  [r`Beyond cost, what barriers limit healthcare access?`]: {
    question: r`A fully insured patient with no copay misses three cardiology appointments. The clinic is 90 minutes away by bus, is open only on weekdays from 9 to 4, and he cannot leave his shift during those hours. Which classification of his barriers is correct?`,
    options: [r`Non-financial access barriers: distance and work hours`, r`Financial access barriers: premiums and deductibles`, r`Provider-side barriers: implicit bias and distrust`, r`Health literacy barriers: forms and instructions`],
    correctAnswer: 0,
    explanation: r`Access is limited by more than cost: transportation, distance and inflexible work hours block care even when insurance is complete. Premiums and deductibles are ruled out by his full coverage with no copay, and nothing in the scenario involves trouble understanding forms or biased treatment by clinicians.`,
  },
  [r`Distinguish health equality from health equity.`]: {
    question: r`A state has $1 million for blood pressure control. Plan 1 gives each of its 10 counties $100,000. Plan 2 gives $250,000 to each of the three counties with the highest stroke death rates and divides the remainder among the other seven. Which statement is correct?`,
    options: [r`Both plans are examples of equity`, r`Plan 1 is equality; Plan 2 is equity`, r`Plan 1 is equity; Plan 2 is equality`, r`Both plans are examples of equality`],
    correctAnswer: 1,
    explanation: r`Equality gives every county the same amount, as Plan 1 does. Equity allocates according to need to reach fair outcomes, as Plan 2 does by directing more money to the counties with the highest stroke deaths. Swapping the labels reverses the definitions, and the two plans differ, so one label cannot fit both.`,
  },
  [r`The {{c1::life-course}} perspective: health reflects accumulating exposures from gestation onward, with sensitive periods and chains of risk.`]: {
    question: r`A researcher explains a 60-year-old's heart disease by tracing her mother's nutrition in pregnancy, her childhood housing, her schooling, and her decades of shift work, treating each as a link in one chain of risk. This approach is the:`,
    options: [r`life-course perspective`, r`illness experience approach`, r`epidemiological transition`, r`health belief model`],
    correctAnswer: 0,
    explanation: r`The life-course perspective treats adult health as the result of exposures that accumulate from gestation onward, with sensitive periods and chains of risk. The health belief model predicts individual preventive actions from beliefs, the epidemiological transition describes changing causes of death in whole societies, and illness experience concerns the subjective meaning of being ill.`,
  },
  [r`The {{c1::weathering}} hypothesis: chronic stress from racism accelerates physiological aging among Black Americans, worsening outcomes at earlier ages.`]: {
    question: r`In a birth registry, rates of low birth weight among white mothers are lowest in the late twenties. Among Black mothers, rates rise steadily from the late teens onward, at every income level. Which hypothesis was proposed to explain this age pattern?`,
    options: [r`Selective migration: healthier mothers move into the group`, r`Medicalization: normal pregnancy is redefined as a disorder`, r`Weathering: cumulative stress from racism ages the body early`, r`Lead-time bias: earlier testing lengthens measured survival`],
    correctAnswer: 2,
    explanation: r`Weathering proposes that chronic stress from racism accelerates physiological aging, so outcomes worsen at earlier ages and independent of income. Selective migration is offered for better than expected immigrant health, lead-time bias is a screening artifact about survival time, and medicalization concerns how conditions get defined, not birth weight.`,
  },
  [r`What characterizes the rural mortality penalty in the US?`]: {
    question: r`A rural county's death rates from heart disease, injury, and overdose exceed those of the nearest city. Which set of conditions is the standard explanation?`,
    options: [r`Overuse of screening, overdiagnosis, and length bias`, r`Younger residents, higher incomes, and more specialists`, r`Dense housing, air pollution, and crowded transit lines`, r`Hospital closures, long travel times, and few clinicians`],
    correctAnswer: 3,
    explanation: r`The rural mortality penalty is driven by provider shortages, hospital closures and long distances to care, in populations that are older and poorer on average. Dense housing and crowded transit describe urban conditions, younger and richer residents with more specialists would lower mortality, and screening artifacts do not raise death rates.`,
  },
  [r`What did the Whitehall studies demonstrate?`]: {
    question: r`A critic says health gaps by social position only reflect poverty and lack of access to care. Why are the Whitehall findings strong evidence against this view?`,
    options: [r`All had jobs and coverage, and deaths were equal at each grade`, r`Only the unemployed and uninsured showed any rise in deaths`, r`All had jobs and coverage, yet deaths rose at each lower grade`, r`Top grades had the most deaths because of high job demands`],
    correctAnswer: 2,
    explanation: r`The Whitehall studies followed British civil servants who were all employed and all covered by the same health system, and mortality still rose stepwise with each lower employment grade. Equal deaths across grades is the opposite of what was found, the study included no unemployed or uninsured group, and the top grades had the lowest mortality, not the highest.`,
  },
  [r`What distinguishes cultural humility from cultural competence?`]: {
    question: r`A clinician says, "I completed a module on this patient's ethnic group, so I already know what she believes about diabetes." The main risk in this statement, and the better alternative, are:`,
    options: [r`stereotyping; cultural competence adds more group modules`, r`medicalization; cultural humility avoids all diagnoses`, r`paternalism; cultural competence defers to the family`, r`stereotyping; cultural humility asks the patient directly`],
    correctAnswer: 3,
    explanation: r`Treating group knowledge as mastered risks stereotyping an individual, which is the standard criticism of cultural competence. Cultural humility is an ongoing stance of self-reflection and learning from the patient herself. More group modules repeat the same error, and neither medicalization nor deferring to the family addresses an assumption about what she believes.`,
  },
  [r`In Parsons's {{c1::sick role}}, the ill are exempted from normal obligations and not blamed, but must want recovery and seek competent help.`]: {
    question: r`A man with diagnosed pneumonia is excused from work and nobody blames him for being ill. He refuses the antibiotics, says he does not care whether he recovers, and skips every follow-up visit. Under Parsons's model, he has:`,
    options: [r`met the duties of the sick role but been denied its rights`, r`shown an illness experience, which has no place in society`, r`claimed the rights of the sick role but not met its duties`, r`been denied the sick role because pneumonia is contested`],
    correctAnswer: 2,
    explanation: r`The sick role pairs two rights, exemption from normal obligations and freedom from blame, with two duties, wanting to recover and seeking competent help. He enjoys both rights while refusing both duties. He has not been denied his rights, pneumonia is a confirmed and uncontested diagnosis, and illness experience is a separate idea about subjective meaning.`,
  },
  [r`Gender paradox: women show higher {{c1::morbidity}} (illness rates) but lower {{c2::mortality}} — living longer while reporting more sickness.`]: {
    question: r`A survey finds that women report more chronic conditions, more sick days, and more physician visits than men, yet women's life expectancy is 5 years longer. In epidemiological terms, women have:`,
    options: [r`higher incidence but lower prevalence`, r`higher morbidity and higher mortality`, r`higher mortality but lower morbidity`, r`higher morbidity but lower mortality`],
    correctAnswer: 3,
    explanation: r`Morbidity is the rate of illness and mortality is the rate of death, so more reported sickness with longer life is higher morbidity and lower mortality. The reversed choice swaps the two terms, incidence and prevalence both measure illness and say nothing about death, and higher mortality contradicts the longer life expectancy.`,
  },
  [r`{{c1::Fundamental cause}} theory (Link and Phelan): SES stays linked to disease across eras because money, knowledge, and networks are flexible resources.`]: {
    question: r`A health agency wants a lasting reduction in the gap in death rates between high and low socioeconomic groups. According to fundamental cause theory, which strategy is most likely to work?`,
    options: [r`Reduce inequality in money, knowledge, and social networks`, r`Release each new treatment first to the wealthiest groups`, r`Wait for medical progress to remove the proximate causes`, r`Target the single risk factor with the widest current gap`],
    correctAnswer: 0,
    explanation: r`Fundamental cause theory holds that flexible resources such as money, knowledge and networks let advantaged groups avoid whatever the current risks are, so only reducing inequality in those resources closes the gap. Fixing one risk factor or waiting for medical progress removes a mechanism that is soon replaced by another, and giving new treatments to the wealthiest first widens the gap.`,
  },
  [r`What are the main mechanisms linking low SES to poor health?`]: {
    question: r`A warehouse worker on low wages lives in a damp apartment, has little say over his shifts, breathes diesel exhaust at work, and lives far from a clinic. A sociologist explaining his raised disease risk should conclude that:`,
    options: [r`one mechanism explains it: lack of health insurance alone`, r`no mechanism applies, since SES only correlates with health`, r`one mechanism explains it: his own choice of health habits`, r`several mechanisms act together: material, stress, and access`],
    correctAnswer: 3,
    explanation: r`Low status harms health through several pathways at once: material deprivation, chronic stress with low control, hazardous work and weaker access to care. Reducing it to personal habits ignores how environment shapes behavior, insurance is only one of the pathways, and the links from status to health are well-described mechanisms, not a bare correlation.`,
  },
  [r`How does stigma affect health and healthcare seeking?`]: {
    question: r`A man with opioid use disorder waits two years before seeking treatment because he fears being judged, tells no one in his family, and at the clinic receives less time from staff than other patients do. The social process behind all three effects is:`,
    options: [r`the sick role for his condition`, r`medicalization of his condition`, r`stigma attached to his condition`, r`low literacy about his condition`],
    correctAnswer: 2,
    explanation: r`Stigma deters care-seeking and disclosure and lowers the quality of care received, which accounts for the delay, the secrecy and the shorter visits. Medicalization would frame addiction as a treatable disorder and tends to ease access, the sick role grants exemption and freedom from blame, and nothing suggests he misunderstands health information.`,
  },
  [r`{{c1::Illness experience}} is the interactionist study of how people manage symptoms, meaning, and identity — central in chronic disease.`]: {
    question: r`A sociologist interviews people with type 1 diabetes about how they decide whom to tell, how they interpret a low-sugar episode at work, and how the diagnosis changed their sense of who they are. This research studies:`,
    options: [r`social epidemiology, a conflict topic`, r`the sick role, an interactionist topic`, r`illness experience, a functionalist topic`, r`illness experience, an interactionist topic`],
    correctAnswer: 3,
    explanation: r`Illness experience is the study of how people manage symptoms, meaning and identity, and it belongs to the symbolic interactionist tradition. Calling it functionalist assigns the wrong perspective. The sick role is a functionalist idea about rights and duties, and social epidemiology studies how disease is distributed across populations.`,
  },
  [r`What are the major criticisms of Parsons's sick role?`]: {
    question: r`A major criticism of Parsons's sick role concerns the kind of patient it describes. For which patient does the model fit most poorly?`,
    options: [r`A child with strep throat kept home on antibiotics briefly`, r`A man with a broken leg who rests and follows his surgeon`, r`A nurse with influenza who takes a week off and recovers`, r`A woman with lifelong multiple sclerosis who works part time`],
    correctAnswer: 3,
    explanation: r`The sick role assumes a temporary exemption that ends with recovery, so it fits acute illness but not chronic disease or disability, where there is no full recovery to pursue and the person keeps many roles. The broken leg, strep throat and influenza are all acute conditions with a clear return to normal duties.`,
  },
  [r`What explains the roughly twofold Black-white infant mortality gap in the US?`]: {
    question: r`Registry data show that infants of Black mothers with college degrees die at higher rates than infants of white mothers who did not finish high school. This finding most directly weakens which explanation of the Black-white infant mortality gap?`,
    options: [r`That it is due to chronic stress from experiencing racism`, r`That it is due to structural rather than genetic factors`, r`That it is due to segregation and unequal quality of care`, r`That it is due to education and income differences alone`],
    correctAnswer: 3,
    explanation: r`If the gap persists at high education levels, socioeconomic differences alone cannot explain it. The finding is consistent with chronic stress from racism and with segregation and unequal care, which affect mothers at every education level, and it supports structural explanations instead of weakening them.`,
  },
  [r`{{c1::Allostatic load}} is cumulative physiological wear from chronic stress — a key mechanism linking low SES and discrimination to disease.`]: {
    question: r`A study measures cortisol, blood pressure, waist-to-hip ratio, and inflammatory markers in each adult and combines them into one index. The index is higher in adults reporting many years of financial strain. The index is designed to measure:`,
    options: [r`relative deprivation`, r`allostatic load`, r`health literacy`, r`acute stress response`],
    correctAnswer: 1,
    explanation: r`Allostatic load is the cumulative physiological wear from chronic stress, seen as dysregulation across cardiovascular, metabolic and immune systems. An acute stress response is a short-lived reaction, not accumulated wear. Relative deprivation is a perception of disadvantage compared with others, and health literacy is the ability to use health information.`,
  },
  [r`{{c1::Food deserts}} are areas with poor access to affordable nutritious food, concentrating diet-related disease in low-income and rural communities.`]: {
    question: r`In one low-income neighborhood, the nearest supermarket is 6 miles away with no bus route, and the only local food sources are two gas stations. A second neighborhood has a supermarket but also 30 fast-food outlets within a mile. The two neighborhoods are best described as:`,
    options: [r`a food swamp, then a food desert`, r`a food swamp in both instances`, r`a food desert, then a food swamp`, r`a food desert in both instances`],
    correctAnswer: 2,
    explanation: r`A food desert lacks access to affordable nutritious food, as in the neighborhood with no reachable supermarket. A food swamp has healthy food available but dominated by unhealthy options, as in the second. The reversed choice swaps the definitions, and one label cannot cover both because only the first neighborhood lacks a supermarket.`,
  },
  [r`A {{c1::DALY}} counts years of healthy life lost to illness and premature death; a {{c2::QALY}} weights years of life gained by their quality.`]: {
    question: r`A health ministry wants (1) to rank diseases by how much healthy life the country loses to each, and (2) to judge whether a new hip implant is worth its price per year of good-quality life gained. The appropriate measures are:`,
    options: [r`QALYs for the ranking, DALYs for the implant`, r`DALYs for the ranking and for the implant`, r`QALYs for the ranking and for the implant`, r`DALYs for the ranking, QALYs for the implant`],
    correctAnswer: 3,
    explanation: r`DALYs count healthy years lost to illness and early death, so they measure burden of disease and suit the ranking. QALYs weight years gained by their quality, so they suit cost-effectiveness analysis of one intervention. The reversed choice swaps loss with gain, and using one measure for both ignores that the first task counts years lost and the second counts years gained.`,
  },
  [r`Which study design suits a rare disease, and which one lets you compute incidence?`]: {
    question: r`Researchers study a cancer that affects 1 in 200,000 people. Team 1 recruits 80 patients and 160 people without the cancer and asks both groups about past solvent exposure. Team 2 wants the rate of new disease among exposed workers. Which statement is correct?`,
    options: [r`Team 1 uses case-control; Team 2 needs cross-sectional`, r`Team 1 uses case-control; Team 2 needs a cohort study`, r`Team 1 uses cross-sectional; Team 2 needs a cohort study`, r`Team 1 uses a cohort study; Team 2 needs case-control`],
    correctAnswer: 1,
    explanation: r`Starting from people with and without a rare disease and looking back at exposure is a case-control design, which is efficient for rare outcomes. Incidence requires following exposed and unexposed groups forward, which is a cohort study. A case-control study cannot give incidence, and a cross-sectional survey gives prevalence at one moment.`,
  },
  [r`{{c1::Single-payer}} means one entity pays for privately delivered care; {{c2::socialized medicine}} means government also owns facilities and staff.`]: {
    question: r`In Country X, a government fund pays all medical bills, but physicians run private practices and hospitals are independent nonprofits. In Country Y, the government owns the hospitals and employs the physicians on salary. The two systems are best described as:`,
    options: [r`socialized medicine in X, single-payer in Y`, r`single-payer in X, private multi-payer in Y`, r`single-payer in X, socialized medicine in Y`, r`private multi-payer in X, single-payer in Y`],
    correctAnswer: 2,
    explanation: r`Single-payer means one entity pays for care that is delivered privately, as in Country X. Socialized medicine means the government also owns the facilities and employs the staff, as in Country Y. The reversed choice swaps the terms, and neither country has multiple private payers because a government fund or government ownership covers everyone.`,
  },
  [r`Ajzen's theory of planned behavior predicts intention from three components. Name them and the model's main limitation.`]: {
    question: r`A woman believes daily walking is good for her, her family and friends all encourage it, and she is confident she can fit it into her day. She firmly intends to walk daily, but after a month she has walked twice because her old evening routine takes over. Which statement fits the theory of planned behavior?`,
    options: [r`Subjective norms were missing, so no real intention was formed`, r`All three predictors were met; this is the intention-behavior gap`, r`All three predictors were met, so the theory is fully confirmed`, r`Perceived control was missing, so no real intention was formed`],
    correctAnswer: 1,
    explanation: r`Attitude, subjective norms and perceived behavioral control were all favorable and produced a firm intention, yet habit overrode it: this is the intention-behavior gap, the model's main limitation. Norms were present because family and friends encouraged her, control was present because she felt confident, and behavior that fails to follow intention does not confirm the theory.`,
  },
  [r`{{c1::Compliance}} implies patient obedience, {{c2::adherence}} implies an agreed plan, and concordance describes shared decision-making about the regimen.`]: {
    question: r`A physician and a patient discuss three regimens, weigh the patient's work schedule and worries about side effects, and choose a once-daily option together. Six months later, pharmacy records show the patient is following the agreed plan. The discussion and the six-month finding illustrate:`,
    options: [r`concordance, then adherence`, r`compliance, then adherence`, r`compliance, then concordance`, r`adherence, then compliance`],
    correctAnswer: 0,
    explanation: r`Concordance is shared decision-making about the regimen, and adherence is following a plan the patient has agreed to. Compliance implies obedience to a clinician's orders, which does not describe either a joint decision or sticking to an agreed plan, so every choice containing compliance mislabels one of the two steps.`,
  },
  [r`{{c1::Medicare}} covers people 65 and older plus those with ESRD or disability; {{c2::Medicaid}} is joint federal-state coverage based on income.`]: {
    question: r`Three people seek public coverage: a 70-year-old retired engineer with substantial savings, a 40-year-old on dialysis for end-stage renal disease, and a 30-year-old parent whose income is below the state threshold. Which programs fit them, in that order?`,
    options: [r`Medicare, Medicaid, Medicaid`, r`Medicare, Medicaid, Medicare`, r`Medicare, Medicare, Medicaid`, r`Medicaid, Medicare, Medicaid`],
    correctAnswer: 2,
    explanation: r`Medicare covers people 65 and older regardless of wealth, and also people with end-stage renal disease or disability. Medicaid is the federal-state program based on income. Assigning Medicaid to the dialysis patient misses the renal disease rule, assigning it to the wealthy retiree confuses age with income, and a 30-year-old with low income does not qualify for Medicare.`,
  },
  [r`Case and Deaton documented rising midlife mortality among less-educated Americans from three causes. Name them and the proposed mechanism.`]: {
    question: r`In one county, mortality among adults aged 45 to 54 without a college degree rose over 15 years while it fell among graduates. If this matches the pattern described by Case and Deaton, the increase came mainly from:`,
    options: [r`influenza, pneumonia, and other infectious disease`, r`suicide, drug overdose, and alcoholic liver disease`, r`homicide, traffic crashes, and workplace accidents`, r`heart disease, stroke, and complications of diabetes`],
    correctAnswer: 1,
    explanation: r`Case and Deaton attributed rising midlife mortality among less-educated Americans to deaths of despair: suicide, drug overdose and alcohol-related liver disease, linked to cumulative disadvantage as stable work disappeared. Cardiovascular disease, infectious disease, and homicide or accidents are not the three causes they identified.`,
  },
  [r`Stages of change: precontemplation, {{c1::contemplation}}, preparation, action, {{c2::maintenance}}, with relapse expected rather than a failure.`]: {
    question: r`A smoker says, "I know I should quit and I have been thinking about it, but I haven't decided on anything yet." Which stage of change is he in, and what should the clinician do?`,
    options: [r`Preparation; set a quit date and a written plan`, r`Maintenance; review ways of preventing relapse`, r`Precontemplation; raise awareness of the risk`, r`Contemplation; weigh pros and cons with him`],
    correctAnswer: 3,
    explanation: r`He recognises the problem and is considering change without a commitment, which is contemplation, and the matched intervention is decisional balance. Precontemplation means he would not yet see a problem, preparation means he has decided and is planning, and maintenance applies only after sustained change.`,
  },
  [r`Name the constructs of the Health Belief Model that predict whether a patient takes a preventive action.`]: {
    question: r`A woman knows she is at risk for cervical cancer, believes it is serious, and believes screening works. She has not been screened because the clinic is two bus rides away and open only during her shifts. Which Health Belief Model construct explains her inaction, and what does the model suggest?`,
    options: [r`Perceived benefits; explain screening`, r`Perceived severity; stress the dangers`, r`Perceived barriers; remove the obstacles`, r`Perceived susceptibility; show her risk`],
    correctAnswer: 2,
    explanation: r`Her beliefs about susceptibility, severity and benefits are already favorable, so what blocks action is perceived barriers, the strongest single predictor in the model. Removing transport and scheduling obstacles works better than more messages. Stressing danger, showing her risk or explaining screening each targets a construct she already holds.`,
  },
  [r`How does structural competency go beyond cultural competency in addressing disparities?`]: {
    question: r`A patient's diabetes is poorly controlled. Clinician 1 asks about his beliefs about insulin and adjusts her explanations. Clinician 2 learns that his insulin spoils because his apartment has no reliable electricity, and connects him with a housing program and a utility assistance fund. Clinician 2 is showing:`,
    options: [r`medical paternalism`, r`cultural relativism`, r`structural competency`, r`cultural competency`],
    correctAnswer: 2,
    explanation: r`Structural competency means recognising how policy, economics and infrastructure produce the clinical problem and intervening at that level, here through housing and utility resources. Cultural competency is Clinician 1's focus on beliefs and communication in the encounter. Cultural relativism is judging practices by their own culture's standards, and paternalism is deciding for the patient.`,
  },
  [r`An uninsured woman in labor arrives at an emergency department. Which law governs the response, and what does it fail to cover?`]: {
    question: r`An uninsured man with chest pain comes to the emergency department of a hospital that accepts Medicare. He is found to have a heart attack and is stabilized. Which service is the hospital NOT obligated to provide under EMTALA?`,
    options: [r`His cardiology follow-up and long-term medications`, r`Stabilizing treatment for the emergency condition`, r`A medical screening examination when he arrives`, r`Emergency care without first proving he can pay`],
    correctAnswer: 0,
    explanation: r`EMTALA requires screening and stabilization of emergency patients regardless of ability to pay, but it is limited to the emergency and does not cover follow-up, medications or chronic care. The screening examination, stabilizing treatment and care without proof of payment are exactly what the law does require.`,
  },
  [r`{{c1::Incidence}} counts new cases arising over a period; {{c2::prevalence}} counts all existing cases at a point in time.`]: {
    question: r`A new drug lets patients with a chronic leukemia live 15 years after diagnosis instead of 5, but it neither cures the disease nor prevents new cases. Over time, the disease's:`,
    options: [r`prevalence rises while incidence stays the same`, r`prevalence falls while incidence stays the same`, r`incidence and prevalence both fall by two thirds`, r`incidence rises while prevalence stays the same`],
    correctAnswer: 0,
    explanation: r`Prevalence counts all existing cases and grows with disease duration, so patients living longer without cure raises it. Incidence counts new cases, which the drug does not change. Saying incidence rises swaps the two measures, and prevalence would fall only if patients were cured or died sooner.`,
  },
  [r`A study finds higher hypertension rates among Black patients and concludes there is a genetic cause. What is the interpretive error?`]: {
    question: r`A report finds that children in one racial group have twice the asthma rate of another and recommends searching for an asthma gene specific to that race. The report did not measure housing quality, air pollution, or access to care. The strongest criticism is that:`,
    options: [r`asthma is never heritable, so genes cannot matter in any child`, r`race is a genetic category, so the sample needs more gene testing`, r`the result is an ecological fallacy, so no group rates are valid`, r`race is a social category, so social confounders likely explain it`],
    correctAnswer: 3,
    explanation: r`Race is a social category that stands in for exposures such as segregation, pollution and unequal care, so unmeasured social confounding is far more plausible than a race-specific gene. Calling race a genetic category repeats the report's error, the claim that asthma is never heritable overstates the case, and comparing group rates is not itself an ecological fallacy.`,
  },
  [r`{{c1::Lead-time}} bias lengthens measured survival by diagnosing earlier; {{c2::length}} bias makes screening oversample slow-growing disease.`]: {
    question: r`A screening test detects a cancer 3 years earlier than symptoms would. Treatment does not change the date of death. Without screening, patients live 2 years after diagnosis. With screening, measured survival after diagnosis is:`,
    options: [r`2 years, an artifact of lead-time bias`, r`5 years, an artifact of length bias`, r`3 years, a real gain in length of life`, r`5 years, an artifact of lead-time bias`],
    correctAnswer: 3,
    explanation: r`Diagnosis moves 3 years earlier while death stays fixed, so survival after diagnosis is 2 + 3 = 5 years with no life gained: lead-time bias. Length bias is different, the tendency of screening to pick up slow-growing disease. Answering 2 years ignores the earlier diagnosis, and 3 years is the lead time itself, which is not a real extension of life.`,
  },
  [r`Physicians shown identical actor-patients describing chest pain referred Black women for catheterization less often. What does this design establish?`]: {
    question: r`In an experiment, physicians watch videos of actors who recite the same chest pain script, with the same listed insurance and history; only the actor's race and sex are randomly varied. Referral rates for catheterization differ by race and sex. Why can the difference be attributed to the physicians' judgments?`,
    options: [r`The actors were sampled to represent real hospital records`, r`Everything except race and sex was held constant by design`, r`Physicians were told the hypothesis before the videos ran`, r`Patients' own treatment preferences varied across videos`],
    correctAnswer: 1,
    explanation: r`Because the script, insurance and history were identical and race and sex were randomly assigned, no difference in presentation, preference or coverage can explain the referral gap, which isolates provider bias. Telling physicians the hypothesis would undermine the study, preferences did not vary because the scripts matched, and representativeness is about generalizing, not about cause.`,
  },
  [r`Meyer's {{c1::minority stress}} model explains sexual and gender minority health gaps via stigma, concealment, and {{c2::internalized}} stigma.`]: {
    question: r`A gay man in an unsupportive town hides his relationship at work and has come to believe negative messages about his identity. He has depressive symptoms despite a high income and a degree. Which model explains this, and what does it call his acceptance of the negative messages?`,
    options: [r`Health belief model; perceived susceptibility`, r`Minority stress model; internalized stigma`, r`Sick role model; exemption from obligations`, r`Minority stress model; concealment of identity`],
    correctAnswer: 1,
    explanation: r`Meyer's minority stress model explains health gaps in sexual and gender minorities through stigma-related stressors that persist after adjusting for income and education. Accepting negative messages about oneself is internalized stigma, while concealment names hiding the relationship. The health belief model predicts preventive actions, and the sick role concerns rights and duties of the ill.`,
  },
  [r`What happens to care quality when patients with limited English proficiency do not receive a professional interpreter?`]: {
    question: r`A Spanish-speaking mother brings her feverish infant to an emergency department. No interpreter is called, and her 11-year-old son translates. Compared with using a trained medical interpreter, this arrangement most likely leads to:`,
    options: [r`more clinically significant errors and weaker consent`, r`fewer clinically significant errors and shorter stays`, r`the same error rate but stronger informed consent`, r`fewer unnecessary tests and better confidentiality`],
    correctAnswer: 0,
    explanation: r`Without a professional interpreter, clinically significant interpretation errors rise and informed consent is weaker, and children used as ad hoc interpreters make the problem worse. Stays become longer, not shorter, unnecessary testing increases, and relying on a family member harms confidentiality.`,
  },
  [r`Why have race coefficients been removed from eGFR and pulmonary function equations?`]: {
    question: r`Under an older kidney equation, a Black patient's result was multiplied by a factor that raised the estimated filtration rate. Two patients, one Black and one white, have identical lab values and true kidney function near a referral cutoff. What was the effect of the race factor?`,
    options: [r`Both patients had the same estimate and the same referral`, r`The Black patient appeared healthier and was referred later`, r`The white patient appeared healthier and was referred later`, r`The Black patient appeared sicker and was referred sooner`],
    correctAnswer: 1,
    explanation: r`A higher estimated filtration rate looks like better kidney function, so the correction made Black patients appear healthier than they were and delayed nephrology referral and transplant listing. The choice that says sicker and sooner gets the direction of the factor wrong, the factor was not applied to white patients, and identical labs did not give identical estimates under the old equation.`,
  },
}
